/* Release-led workspace extension. Reuses Creovibe frames and existing form helpers. */
const E=window.CareerEngine;
state=E.migrate(state);
names.career='Career Progress';names.roadmap='Roadmap';
let releaseFilter='all';
let reportMode='quarter',reportAnchor=today(),customStart=today().slice(0,4)+'-01-01',customEnd=today();
function record(type,entityId,text,extra={}){state.events.push({id:uid(),type,entityId,time:new Date().toISOString(),date:today(),text,...extra});log(text);}
function adapt(reason){const result=E.schedule(state,today());state.scheduleWarnings=result.warnings;if(result.updates.length){const revision={id:uid(),time:new Date().toISOString(),reason,changes:result.updates,undone:false};for(const change of result.updates)Object.assign(state.tasks.find(t=>t.id===change.id),change.after);state.revisions.push(revision);record('schedule_adjusted',revision.id,reason,{changes:result.updates.length});}return result;}
function scheduleNotice(){const rev=[...state.revisions].reverse().find(r=>!r.undone);return `<section class="panel scheduling-note"><div class="panel-head"><h2>What changed and why</h2>${rev?`<button class="text-link" data-undo="${rev.id}">Undo</button>`:''}</div><p class="small-copy muted">${rev?esc(rev.reason)+' · '+rev.changes.length+' suggested task date/order updates.':'Your plan adjusts when release dates, availability, or task status changes. Your chosen dates and release dates stay fixed.'}</p>${rev?`<details><summary>View adjustments</summary>${rev.changes.map(c=>`<p class="small-copy">${esc(state.tasks.find(t=>t.id===c.id)?.title||'Task')}: ${c.before.due?date(c.before.due):'Unscheduled'} → ${date(c.after.due)}${c.before.due===c.after.due?' · priority updated':''}</p>`).join('')}</details>`:''}${(state.scheduleWarnings||[]).length?`<ul class="schedule-warnings">${state.scheduleWarnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}</section>`;}
const oldOverview=overview;
overview=function(){let html=oldOverview();html=html.replace('Your first roadmap','Your first release').replace('href="#roadmap" class="setup-item','href="#releases" class="setup-item');return html+`<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Your whole career, over time</h2>${link('Open Career Progress','career')}</div><p class="muted">Review releases, actions, performances, collaborations, learning, audience observations and finances by quarter or year.</p></section>`;};
setup=function(){return [!!state.profile.artist,!!state.history.length,!!state.releases.length];};
const originalProfile=profile;
profile=function(){return originalProfile().replace('Save and continue','Save and plan a release');};
const originalTaskRow=taskRow;
taskRow=function(t){return originalTaskRow(t).replace(`<small>${esc(t.domain||'Personal task')}`,`<small>${t.releaseId?esc(state.releases.find(r=>r.id===t.releaseId)?.title||'Release')+' · ':''}${E.blocked(state,t)?'Waiting on a prerequisite · ':''}${esc(t.domain||'Personal task')}`);};
activeTasks=function(){return state.tasks.filter(t=>!t.archived&&(!t.releaseId||state.releases.find(r=>r.id===t.releaseId)?.status!=='Archived')).sort((a,b)=>Number(E.blocked(state,a))-Number(E.blocked(state,b))||(a.order??999)-(b.order??999)||(a.due||'9999').localeCompare(b.due||'9999'));};
function projectOptions(selected='all',includeAll=true){return (includeAll?'<option value="all">All projects</option>':'')+`<option value="general" ${selected==='general'?'selected':''}>General career work</option>`+state.releases.map(r=>`<option value="${r.id}" ${selected===r.id?'selected':''}>${esc(r.title)}</option>`).join('');}
roadmap=function(){const p=progress();return header('Your release. A living plan.','Plan, build, act, and adjust. Your roadmap follows the work you do.',btn('Add task','add-task'))+`<div class="toolbar"><label class="field"><span>Project</span><select id="release-filter">${projectOptions(releaseFilter)}</select></label><div class="filters">${['All','To do','In progress','Done','Deferred'].map(v=>`<button class="filter ${taskFilter===v?'active':''}" data-filter="${v}">${v}</button>`).join('')}</div><input class="search-input" aria-label="Search tasks" placeholder="Search your tasks…" value="${esc(query)}" id="task-search"></div><p class="welcome-note">${p.done} of ${p.total} actions completed across active projects. Prerequisites are shown; dates you set are protected.</p>${scheduleNotice()}<section class="panel"><div id="task-results">${taskResults()}</div></section><div class="form-actions">${btn('Review general career suggestions','refresh-plan','arrows-rotate')}<small>These support your career beyond individual release plans.</small></div>`;};
taskResults=function(){const tasks=activeTasks().filter(t=>(releaseFilter==='all'||(releaseFilter==='general'?!t.releaseId:t.releaseId===releaseFilter))&&(taskFilter==='All'||t.status===taskFilter)&&t.title.toLowerCase().includes(query.toLowerCase()));return tasks.length?tasks.map(taskRow).join(''):empty('Choose what you’re building.','Create a release to generate its roadmap, or add a general career task.',`<a href="#releases" class="text-link">Plan a release</a>`);};
const oldApplyPlan=applyPlan;
applyPlan=function(){// General recommendations must never archive release work.
 const releaseTasks=state.tasks.filter(t=>t.releaseId);state.tasks=state.tasks.filter(t=>!t.releaseId);oldApplyPlan();state.tasks.push(...releaseTasks);state=E.migrate(state);adapt('General career priorities reviewed');save();render();};
releases=function(){return header('Start with the music you’re building.','Create a release. Its roadmap follows you from preparation to review.',btn('New release','add-release'))+(state.releases.length?`<div class="release-grid">${state.releases.map(r=>{const tasks=state.tasks.filter(t=>t.releaseId===r.id&&!t.archived),done=tasks.filter(t=>t.status==='Done').length;return `<article class="release-card"><div class="release-art"><img src="images/artists/speaker.jpg" alt=""><span class="tag">${esc(r.type)}</span></div><div class="release-body"><h2>${esc(r.title)}</h2><p>${esc(r.goal||'Add your release goal')}</p><p>${date(r.date)} · ${esc(r.status)}</p><div class="track" role="img" aria-label="${done} of ${tasks.length} release actions completed"><span style="width:${tasks.length?done/tasks.length*100:0}%"></span></div><p style="margin-top:10px">${done} of ${tasks.length} actions complete · Budget ${money(r.budget)}</p><button class="theme-btn-two" data-release="${r.id}">Manage release <i class="fa-light fa-pen"></i></button><button class="text-link" style="display:block;margin-top:16px" data-project="${r.id}">Open this roadmap</button></div></article>`}).join('')}</div>`:`<section class="panel">${empty('What are you releasing next?','A single, EP or album becomes a connected plan across preparation, production, delivery, promotion and review.',btn('Create your first release','add-release'))}</section>`);};
releaseDialog=function(id){const r=state.releases.find(r=>r.id===id)||{title:'',goal:'',type:'Single',status:'Planning',date:'',budget:'',milestones:[]};openDialog(id?'Manage your release':'Start a release',`<form id="release-form" data-id="${id||''}"><div class="fields"><div class="full">${field('Release title','title',r.title,'text','required maxlength="120"')}</div><div class="full">${field('Release goal','goal',r.goal,'text','required maxlength="250" placeholder="What should this release achieve?"')}</div>${select('Release type','type',['Single','EP','Album'],r.type,true)}${select('Status','status',['Planning','In production','Scheduled','Released','Archived'],r.status,true)}${field('Target release date','date',r.date,'date','required')}${field('Project budget ('+(state.profile.currency||'GBP')+')','budget',r.budget,'number','min="0" step="0.01" max="100000000"')}${field('Actual release date (when released)','deliveredDate',r.deliveredDate||'','date')}</div>${id?`<p style="margin-top:20px">Milestones follow completed roadmap actions. Edit the task to complete or reopen a phase.</p><div class="check-list">${E.phases.map(([phase,label])=>{const task=state.tasks.find(t=>t.id===id+':'+phase);return `<label><i class="fa-light fa-${task?.status==='Done'?'check':'circle'}"></i>${label}${task?.status==='Done'?' · complete':''}</label>`}).join('')}</div>`:'<p style="margin-top:20px">Saving creates five connected actions. Your assessment informs preparation, and your available time shapes suggested dates.</p>'}<div class="form-actions"><button class="theme-btn-two">${id?'Save release':'Create release and roadmap'} <i class="fa-light fa-check"></i></button></div></form>`);};
taskDialog=function(id){const t=state.tasks.find(t=>t.id===id)||{title:'',status:'To do',due:'',notes:'',effort:30,dateMode:'auto',releaseId:releaseFilter!=='all'&&releaseFilter!=='general'?releaseFilter:null};openDialog(id?'Work on your next step':'Add a task',`<form id="task-form" data-id="${id||''}"><div class="fields"><div class="full">${field('Task title','title',t.title,'text','required maxlength="150"')}</div><label class="field"><span>Project</span><select name="releaseId" ${t.phase?'disabled':''}>${projectOptions(t.releaseId||'general',false)}</select></label>${select('Status','status',['To do','In progress','Done','Deferred'],t.status,true)}${field('Target date','due',t.due,'date')}${field('Estimated effort (minutes)','effort',t.effort||30,'number','required min="5" max="100000" step="5"')}<label class="field full"><span>Date control</span><select name="dateMode"><option value="auto" ${t.dateMode==='auto'?'selected':''}>Let the roadmap schedule this date</option><option value="manual" ${t.dateMode==='manual'?'selected':''}>Keep my chosen date fixed</option></select></label><label class="field full"><span>Notes</span><textarea name="notes" maxlength="2000">${esc(t.notes)}</textarea></label></div>${E.blocked(state,t)?'<p class="schedule-warnings">A prerequisite is unfinished. You can still record work already done; dependent scheduling will flag the conflict.</p>':''}${t.steps?`<div style="margin-top:24px"><span class="eyebrow">Why this action</span><p>${esc(t.reason)}</p><span class="eyebrow">Start here</span><p>${esc(t.steps)}</p>${t.phase==='prepare'?`<p>Foundation gaps: ${domains.filter(([key])=>['no','partial'].includes(state.answers[key])).map(d=>esc(d[1])).join(', ')||'Review your foundations to find gaps before delivery.'}</p>`:''}${t.url?`<a class="text-link" href="${t.url}">Open related guidance</a>`:''}</div>`:''}<div class="form-actions"><button class="theme-btn-two">Save task <i class="fa-light fa-check"></i></button>${id&&!t.phase?`<button type="button" class="text-link" data-archive="${id}">Archive task</button>`:''}</div></form>`);};
function transition(t,status){const prev=t.status;t.status=status;if(prev===status)return;record(status==='Done'?'task_completed':prev==='Done'?'task_reopened':'task_status_changed',t.id,(status==='Done'?'Completed: ':status==='Deferred'?'Deferred: ':'Updated: ')+t.title,{releaseId:t.releaseId||null,from:prev,to:status});if(status==='Done')t.completedAt=new Date().toISOString();else if(prev==='Done')t.completedAt=null;if(t.phase){const r=state.releases.find(r=>r.id===t.releaseId);const m=r.milestones.find(m=>m.phase===t.phase)||{phase:t.phase};if(!r.milestones.includes(m))r.milestones.push(m);m.done=status==='Done';if(status==='Done'){m.completedAt=new Date().toISOString();record('milestone_completed',t.id,'Milestone achieved: '+t.domain,{releaseId:r.id});}else if(prev==='Done')record('milestone_reopened',t.id,'Milestone reopened: '+t.domain,{releaseId:r.id});}}
function activityDialog(id){const a=state.careerActivities.find(a=>a.id===id)||{date:today(),category:'Gig',description:'',outcome:'',releaseId:null};openDialog(id?'Edit career activity':'Log a career activity',`<form id="activity-form" data-id="${id||''}"><div class="fields">${field('Activity date','date',a.date,'date','required')}${select('Category','category',['Gig','Collaboration','Networking','Learning','Audience engagement','Other'],a.category,true)}<div class="full">${field('Description','description',a.description,'text','required maxlength="250"')}</div><label class="field full"><span>Outcome or learning</span><textarea name="outcome" maxlength="1500">${esc(a.outcome)}</textarea></label><label class="field full"><span>Related release (optional)</span><select name="releaseId">${projectOptions(a.releaseId||'general',false)}</select></label></div><div class="form-actions"><button class="theme-btn-two">Save activity <i class="fa-light fa-check"></i></button></div></form>`);}
function observationDialog(id){const o=state.observations.find(o=>o.id===id)||{platform:'',metric:'',value:'',periodStart:today(),periodEnd:today()};openDialog(id?'Edit audience observation':'Record an audience observation',`<form id="observation-form" data-id="${id||''}"><div class="fields">${field('Platform or source','platform',o.platform,'text','required maxlength="80" placeholder="e.g. Spotify"')}${field('Metric and unit','metric',o.metric,'text','required maxlength="100" placeholder="e.g. Monthly listeners"')}${field('Value','value',o.value,'number','required min="0" step="0.01" max="1000000000000"')}${field('Period start','periodStart',o.periodStart,'date','required')}${field('Period end','periodEnd',o.periodEnd,'date','required')}</div><p style="margin-top:20px">Record the period reported by the platform. Different metrics or periods are kept separate, never added together.</p><div class="form-actions"><button class="theme-btn-two">Save observation <i class="fa-light fa-check"></i></button></div></form>`);}
function careerProgress(){const range=E.period(reportMode,reportAnchor,today(),customStart,customEnd);if(range.start>range.end)return header('Your career, in perspective.','Choose a valid date range.')+reportControls()+`<p role="alert">The start date must be before the end date.</p>`;const stats=E.summary(state,range),previous=range.previous?E.summary(state,range.previous):null;const card=(label,value,prior)=>`<div class="stat-box"><div class="stat-top">${label}</div><div class="stat-number">${value}</div><p>${prior!==undefined?prior+' in previous '+(reportMode==='year'?'year':'quarter'):'Selected period'}</p></div>`;
 const timeline=[...stats.events.filter(e=>e.type!=='schedule_adjusted').map(e=>({date:e.date||e.time,title:e.text,kind:'Workspace activity'})),...stats.activities.map(a=>({date:a.date,title:a.description,kind:a.category,outcome:a.outcome,id:a.id})),...stats.assessments.map(a=>({date:a.time,title:'Foundations: '+(a.score===null?'Not assessed':a.score+'/100'),kind:'Assessment'})),...state.entries.filter(e=>e.date>=range.start&&e.date<=range.end).map(e=>({date:e.date,title:e.description+' · '+money(e.amount),kind:e.type}))].sort((a,b)=>b.date.localeCompare(a.date));
 return header('Your career, in perspective.','A holistic view of your work, engagements and outcomes over time.',btn('Log activity','add-activity'))+reportControls()+`<p class="welcome-note">${reportMode==='all'?'All recorded history':date(range.start)+' – '+date(range.end)}${range.partial?' · Partial period: future dates have no observations yet. Comparisons show full prior periods.':''}${range.future?' · This period starts in the future.':''}</p><div class="stats-row">${card('Releases delivered',stats.delivered,previous?.delivered)}${card('Actions completed',stats.completions,previous?.completions)}${card('Milestones achieved',stats.milestones,previous?.milestones)}${card('Career engagements',stats.activities.length,previous?.activities.length)}${card('Recorded income',money(stats.income),previous?money(previous.income):undefined)}${card('Recorded expenses',money(stats.expenses),previous?money(previous.expenses):undefined)}</div><div class="dashboard-grid"><section class="panel"><h2>Career timeline</h2><p class="small-copy muted">Actions and outcomes are separate. Task completion does not imply audience or income growth.</p>${timeline.length?timeline.map(x=>`<div class="task-row"><div class="task-main"><b>${esc(x.title)}</b><small>${date(x.date.slice(0,10))} · ${esc(x.kind)}</small>${x.outcome?`<p class="small-copy muted">${esc(x.outcome)}</p>`:''}</div>${x.id?`<button class="icon-button" data-activity="${x.id}" aria-label="Edit activity"><i class="fa-light fa-pen"></i></button>`:''}</div>`).join(''):empty('Your story is still taking shape.','Log a real activity or complete a planned action to build this view.')}</section><div><section class="panel"><h2>Engagement breakdown</h2>${Object.keys(stats.categories).length?Object.entries(stats.categories).map(([cat,n])=>`<div class="foundation-item"><span>${esc(cat)}</span><div class="track" role="img" aria-label="${esc(cat)}: ${n} activities"><span style="width:${n/stats.activities.length*100}%"></span></div><b>${n}</b></div>`).join(''):'<p class="small-copy muted">No manually logged engagements in this period.</p>'}</section><section class="panel" style="margin-top:22px"><h2>Financial trend</h2><p class="small-copy muted">Actual dated records, grouped by month. Not a bank balance.</p>${financialTrend(range)}</section></div></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Audience observations</h2>${btn('Record observation','add-observation')}</div><p class="small-copy muted">Manual observations. Different sources, metrics and measurement windows remain separate. Missing values are unknown.</p>${stats.observations.length?`<div class="table-wrap"><table><thead><tr><th>Source</th><th>Metric</th><th>Period</th><th>Value</th><th>Action</th></tr></thead><tbody>${stats.observations.map(o=>`<tr><td>${esc(o.platform)}</td><td>${esc(o.metric)}</td><td>${date(o.periodStart)} – ${date(o.periodEnd)}</td><td>${Number(o.value).toLocaleString()}</td><td><button class="icon-button" data-observation="${o.id}" aria-label="Edit observation"><i class="fa-light fa-pen"></i></button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No observations recorded for this period.</p>'}</section><details class="panel" style="margin-top:22px"><summary>Legacy history and reporting notes</summary><p class="small-copy muted">Completed counts represent distinct actions achieved during the period; reopening does not erase that historical work. Repeated completions of the same task count once per period. Audience observations are grouped by period end. Earlier demo entries do not imply verified milestone or release outcomes.</p>${(state.activity||[]).filter(a=>!state.events.some(e=>e.time===a.time&&e.text===a.text)).map(a=>`<p class="small-copy muted">${a.time?date(a.time.slice(0,10)):'Date unknown'} · ${esc(a.text)}</p>`).join('')}</details>`;}
function reportControls(){return `<div class="toolbar report-controls"><div class="filters">${[['quarter','Quarterly'],['year','Yearly'],['all','All time'],['custom','Custom dates']].map(([v,l])=>`<button class="filter ${reportMode===v?'active':''}" data-period="${v}">${l}</button>`).join('')}</div>${['quarter','year'].includes(reportMode)?`<label class="field"><span>Select a date in the ${reportMode}</span><input type="date" id="report-anchor" value="${reportAnchor}"></label>`:reportMode==='custom'?`<label class="field"><span>From</span><input type="date" id="report-start" value="${customStart}"></label><label class="field"><span>To</span><input type="date" id="report-end" value="${customEnd}"></label>`:''}</div>`;}
function financialTrend(range){const months={};for(const e of state.entries.filter(e=>e.date>=range.start&&e.date<=range.end)){const key=e.date.slice(0,7);months[key]??={Income:0,Expense:0};months[key][e.type]+=Math.round(Number(e.amount)*100);}return Object.keys(months).length?`<div class="table-wrap"><table><thead><tr><th>Month</th><th>Income</th><th>Expenses</th></tr></thead><tbody>${Object.keys(months).sort().map(m=>`<tr><td>${m}</td><td>${money(months[m].Income/100)}</td><td>${money(months[m].Expense/100)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small-copy muted">No financial entries in this period.</p>';}
document.addEventListener('submit',e=>{const f=e.target;const handled=['profile-form','assessment-form','task-form','release-form','entry-form','activity-form','observation-form'];if(!handled.includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));
 if(f.id==='profile-form'){if(!data.artist.trim()){toast('Please enter an artist name.');return;}if((state.entries.length||state.releases.some(r=>Number(r.budget)>0))&&data.currency!==(state.profile.currency||'GBP')){toast('Keep the current currency while financial records exist.');return;}const changed=state.profile.hours!==data.hours;state.profile={...state.profile,...data,artist:data.artist.trim()};record('profile_updated','profile','Updated artist profile');if(changed)adapt('Weekly availability changed; suggested dates recalculated');save('Artist profile saved.');render();}
 if(f.id==='assessment-form'){state.answers=Object.fromEntries(Object.entries(data).filter(([k])=>!k.startsWith('context_')));const s=score();state.history.push({time:new Date().toISOString(),answers:{...state.answers},context:{...state.profile},score:s.value,count:s.count});log('Reviewed career foundations');adapt('Foundations reviewed; release preparation guidance updated');save('Assessment saved. Your career recommendations are ready.');location.hash='roadmap';render();}
 if(f.id==='task-form'){if(!data.title.trim()){toast('Please enter a task title.');return;}const existing=state.tasks.find(t=>t.id===f.dataset.id);const status=data.status;let mode=data.dateMode;if(existing&&data.due!==existing.due&&data.due)mode='manual';if(mode==='manual'&&!data.due){toast('Choose a date to keep fixed, or use automatic scheduling.');return;}if(existing){transition(existing,status);Object.assign(existing,{title:data.title.trim(),due:data.due,dateMode:mode,effort:Number(data.effort),notes:data.notes,releaseId:existing.phase?existing.releaseId:data.releaseId==='general'?null:data.releaseId});}else{const task={...data,id:uid(),title:data.title.trim(),dateMode:mode,effort:Number(data.effort),releaseId:data.releaseId==='general'?null:data.releaseId,domain:'Personal task',generated:false,archived:false,dependencies:[],status:'To do',order:999};state.tasks.push(task);transition(task,status);record('task_created',task.id,'Created task: '+task.title,{releaseId:task.releaseId});}adapt('Task updated; prerequisites, priorities and suggested dates reviewed');save('Task saved. Roadmap adjusted.');closeDialog();render();}
 if(f.id==='release-form'){if(!data.title.trim()||!data.goal.trim()){toast('Enter a release title and goal.');return;}if(data.status==='Released'&&(!data.deliveredDate||data.deliveredDate>today())){toast('Record the actual release date, no later than today.');return;}const old=state.releases.find(r=>r.id===f.dataset.id),previousStatus=old?.status,previousDelivered=old?.deliveredDate;const r={id:old?.id||uid(),title:data.title.trim(),goal:data.goal.trim(),type:data.type,status:data.status,date:data.date,budget:data.budget,deliveredDate:data.deliveredDate||'',milestones:old?.milestones||[]};if(old)Object.assign(old,r);else state.releases.push(r);E.seed(state,r);record(old?'release_updated':'release_created',r.id,(old?'Updated release: ':'Created release: ')+r.title,{releaseId:r.id});if(r.status==='Released'&&(previousStatus!=='Released'||previousDelivered!==r.deliveredDate)){// Correct the factual delivery date rather than counting edits as new releases.
 const delivered=state.events.find(x=>x.type==='release_delivered'&&x.entityId===r.id);if(delivered){delivered.time=r.deliveredDate+'T12:00:00';delivered.date=r.deliveredDate;delivered.text='Released: '+r.title;}else record('release_delivered',r.id,'Released: '+r.title,{time:r.deliveredDate+'T12:00:00',date:r.deliveredDate,releaseId:r.id});}if(previousStatus==='Released'&&r.status!=='Released'&&r.status!=='Archived'){state.events=state.events.filter(x=>!(x.type==='release_delivered'&&x.entityId===r.id));record('release_delivery_corrected',r.id,'Corrected release status: '+r.title,{releaseId:r.id});}adapt(old?'Release details changed; unfinished suggested work rescheduled':'Release created; five-phase roadmap scheduled');save('Release saved. Your roadmap is ready.');closeDialog();releaseFilter=r.id;location.hash='roadmap';render();}
 if(f.id==='entry-form'){if(!data.description.trim()){toast('Enter a description.');return;}data.amount=Number(data.amount);const old=state.entries.find(x=>x.id===f.dataset.id);if(old)Object.assign(old,data);else state.entries.push({...data,id:uid()});save('Financial entry saved. Career Progress updated.');closeDialog();render();}
 if(f.id==='activity-form'){if(!data.description.trim()){toast('Enter an activity description.');return;}if(data.date>today()){toast('Log completed engagements using today or an earlier date. Use roadmap tasks for future plans.');return;}const old=state.careerActivities.find(a=>a.id===f.dataset.id),item={...data,description:data.description.trim(),releaseId:data.releaseId==='general'?null:data.releaseId,id:old?.id||uid()};if(old)Object.assign(old,item);else state.careerActivities.push(item);save('Career activity saved.');closeDialog();render();}
 if(f.id==='observation-form'){if(data.periodStart>data.periodEnd||data.periodEnd>today()){toast('Use a valid completed measurement period ending no later than today.');return;}if(!data.platform.trim()||!data.metric.trim()){toast('Enter a source and metric.');return;}const old=state.observations.find(o=>o.id===f.dataset.id),item={...data,platform:data.platform.trim(),metric:data.metric.trim(),value:Number(data.value),id:old?.id||uid()};if(old)Object.assign(old,item);else state.observations.push(item);save('Audience observation saved.');closeDialog();render();}
});
document.addEventListener('change',e=>{const target=e.target;if(target.matches('[data-complete]')){const t=state.tasks.find(t=>t.id===target.dataset.complete);transition(t,target.checked?'Done':'To do');adapt(target.checked?'Action completed; next steps unlocked and suggested work adjusted':'Action reopened; dependent work and suggested dates reviewed');save('Progress saved. Roadmap updated.');render();}if(target.id==='release-filter'){releaseFilter=target.value;render();}if(target.id==='report-anchor'&&target.value){reportAnchor=target.value;render();}if(target.id==='report-start'&&target.value){customStart=target.value;render();}if(target.id==='report-end'&&target.value){customEnd=target.value;render();}});
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='add-activity')activityDialog();if(action==='add-observation')observationDialog();const activity=e.target.closest('[data-activity]');if(activity)activityDialog(activity.dataset.activity);const observation=e.target.closest('[data-observation]');if(observation)observationDialog(observation.dataset.observation);const project=e.target.closest('[data-project]');if(project){releaseFilter=project.dataset.project;location.hash='roadmap';render();}const periodButton=e.target.closest('[data-period]');if(periodButton){reportMode=periodButton.dataset.period;render();}const undo=e.target.closest('[data-undo]');if(undo){const rev=state.revisions.find(r=>r.id===undo.dataset.undo);if(!rev||rev.undone)return;for(const c of rev.changes){const t=state.tasks.find(t=>t.id===c.id);if(!t||t.status==='Done'||t.status==='Deferred'||t.dateMode==='manual')continue;if(t.due===c.after.due&&t.order===c.after.order)Object.assign(t,c.before);}rev.undone=true;record('schedule_undone',rev.id,'Undid automatic scheduling changes');state.scheduleWarnings=['Scheduling changes were undone. The triggering action remains saved. Timing will be reviewed again after your next change.'];save('Automatic dates and order restored where still applicable.');render();}});
// Reset must retain the v3 structure. It does not erase unrelated legacy storage.
document.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-reset"]')){e.stopImmediatePropagation();state=E.migrate(fresh());save('Local workspace reset.');closeDialog();location.hash='overview';render();}},true);
// Preserve legacy records while adding usable release plans. Do not infer historical completion dates.
for(const release of state.releases)E.seed(state,release);
if(state.tasks.some(t=>t.releaseId&&!t.suggestedDate))adapt('Existing releases connected to their roadmaps; historical records preserved');
save();render();
